typedef float rational_t;

class vector3d
{
public:
  vector3d(const vector3d&);
  vector3d& operator=(const vector3d&);
  vector3d& operator*=(rational_t);
};

vector3d operator+(const vector3d&, const vector3d&);

class po
{
public:
  const vector3d& get_facing() const;
};

class entity
{
public:
  const po& get_abs_po() const;
  const vector3d& get_abs_position() const;
  void set_rel_position(const vector3d&);
};

class motion_control_system
{
public:
  virtual ~motion_control_system();
  virtual void frame_advance(float) = 0;
protected:
  char layout_pad[8];
  entity* ent;
};

class dolly_and_strafe_mcs : public motion_control_system
{
public:
  virtual ~dolly_and_strafe_mcs();
  virtual void frame_advance(float);
private:
  rational_t dolly;
  rational_t strafe;
  rational_t lift;
  void do_dolly(rational_t distance);
  void do_lift(rational_t distance);
  void do_strafe(rational_t distance);
};

void dolly_and_strafe_mcs::do_dolly( rational_t distance )
{
  // get direction facing
  vector3d facing = ent->get_abs_po().get_facing();
  // multiply distance by it
  facing *= distance;
  // add it to position
  ent->set_rel_position( ent->get_abs_position() + facing );
}
